using namespace std;

int main() {
    string s;
    cin >> s;
    // Palindromic tree: node 0 has length -1, node 1 has length 0.
    vector<int> length{-1, 0}, link{0, 0};
    vector<array<int, 26>> edge(2);
    edge[0].fill(-1);
    edge[1].fill(-1);
    int last = 1;
    for (int i = 0; i < (int)s.size(); i++) {
