import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        // Palindromic tree: node 0 has length -1, node 1 has length 0.
        int[] length = new int[n + 2], link = new int[n + 2];
        int[][] edge = new int[n + 2][26];
        for (int[] row : edge) Arrays.fill(row, -1);
        length[0] = -1;
        int nodes = 2, last = 1;
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            int c = ch - 'a', p = last;
            while (i - 1 - length[p] < 0 || s.charAt(i - 1 - length[p]) != ch) p = link[p];
            if (edge[p][c] < 0) {
                int node = nodes++;
                length[node] = length[p] + 2;
                link[node] = 1;
                edge[p][c] = node;
                if (length[node] > 1) {
                    int q = link[p];
                    while (i - 1 - length[q] < 0 || s.charAt(i - 1 - length[q]) != ch) q = link[q];
                    link[node] = edge[q][c];
                }
            }
            last = edge[p][c];
        }
        System.out.println(nodes - 2);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := token()
	// Palindromic tree: node 0 has length -1, node 1 has length 0.
	length := []int{-1, 0}
	link := []int{0, 0}
	empty := [26]int{}
	for i := range empty {
		empty[i] = -1
	}
	edge := [][26]int{empty, empty}
	last := 1
	for i := range s {
		c, p := int(s[i]-'a'), last
		for i-1-length[p] < 0 || s[i-1-length[p]] != s[i] {
			p = link[p]
		}
		if edge[p][c] < 0 {
			node := len(length)
			length = append(length, length[p]+2)
			link = append(link, 1)
			edge = append(edge, empty)
			edge[p][c] = node
			if length[node] > 1 {
				q := link[p]
				for i-1-length[q] < 0 || s[i-1-length[q]] != s[i] {
					q = link[q]
				}
				link[node] = edge[q][c]
			}
		}
		last = edge[p][c]
	}
	fmt.Println(len(length) - 2)
}
